{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "finding-report@1",
  "title": "FindingReport",
  "description": "Confirmed bugs in live code. Every finding includes the exact trigger condition and root cause.",
  "type": "object",
  "required": ["workspace", "language", "findings"],
  "additionalProperties": false,
  "properties": {
    "workspace": {
      "type": "string",
      "description": "Absolute path to the workspace root"
    },
    "language": {
      "type": "string",
      "description": "Primary language of the scanned code (e.g. rust, typescript)"
    },
    "modules_scanned": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Modules or files included in the scan (live code only)"
    },
    "dead_files_excluded": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Files excluded because they are unreachable from the crate root or entry point"
    },
    "findings": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["id", "description", "file", "line", "severity", "trigger_condition", "root_cause", "verdict"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "description": { "type": "string" },
          "file": { "type": "string" },
          "line": { "type": "integer", "minimum": 1 },
          "severity": { "enum": ["critical", "high", "medium", "low"] },
          "trigger_condition": {
            "type": "string",
            "description": "Exact input, state, or call sequence that reproduces the bug"
          },
          "root_cause": { "type": "string" },
          "remediation_sketch": {
            "type": "string",
            "description": "One-sentence description of the fix — not prescriptive code"
          },
          "verdict": {
            "enum": ["confirmed", "plausible"],
            "description": "confirmed = adversary could not refute; plausible = needs human review"
          }
        }
      }
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}
---
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "verdict@1",
  "title": "Verdict",
  "description": "The axiom exit gate result. Pass or fail, with specific blockers on failure.",
  "type": "object",
  "required": ["verdict", "confidence", "verdict_summary"],
  "additionalProperties": false,
  "properties": {
    "verdict": {
      "enum": ["pass", "fail"],
      "description": "Whether the artifact meets its criteria"
    },
    "confidence": {
      "enum": ["high", "medium", "low"],
      "description": "Confidence in the verdict"
    },
    "blockers": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["criterion", "finding"],
        "additionalProperties": false,
        "properties": {
          "criterion": {
            "type": "string",
            "description": "The specific criterion that failed"
          },
          "finding": {
            "type": "string",
            "description": "What was found — specific, actionable, not generic"
          },
          "location": {
            "type": "string",
            "description": "File path and line number if applicable"
          }
        }
      },
      "description": "Required when verdict is fail. Each blocker must give the producing agent enough information to fix the issue."
    },
    "verdict_summary": {
      "type": "string",
      "maxLength": 300,
      "description": "One paragraph readable by a human or orchestrator. States what passed, what failed, and what happens next."
    },
    "artifact_type": {
      "type": "string",
      "description": "The schema ID of the artifact that was verified (e.g. spec@1)"
    },
    "retry_count": {
      "type": "integer",
      "minimum": 0,
      "description": "How many times this artifact has been through the gate. Escalate at 3."
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}
---
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "plan@1",
  "title": "Plan",
  "description": "A sequenced implementation plan. Every task is bite-sized, TDD-first, with exact code and commit message.",
  "type": "object",
  "required": ["goal", "architecture", "tech_stack", "tasks"],
  "additionalProperties": false,
  "properties": {
    "goal": {
      "type": "string",
      "description": "One sentence: what this plan produces"
    },
    "architecture": {
      "type": "string",
      "description": "2-3 sentences on the implementation approach"
    },
    "tech_stack": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Key libraries, frameworks, or runtimes involved"
    },
    "tasks": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["id", "title", "files", "steps", "commit_message"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "title": { "type": "string" },
          "files": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "create": { "type": "array", "items": { "type": "string" } },
              "modify": { "type": "array", "items": { "type": "string" } },
              "test": { "type": "array", "items": { "type": "string" } }
            }
          },
          "steps": {
            "type": "array",
            "minItems": 1,
            "items": { "type": "string" },
            "description": "Ordered steps. Each step is one action. Code steps include exact code. Test steps include exact command and expected output."
          },
          "commit_message": {
            "type": "string",
            "description": "Conventional commit message for this task"
          },
          "depends_on": {
            "type": "array",
            "items": { "type": "string" },
            "description": "IDs of tasks that must complete before this one"
          }
        }
      }
    },
    "linked_spec": {
      "type": "string",
      "description": "ID of the spec@1 this plan implements"
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}

